import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import * as GaussianSplats3D from "@mkkellogg/gaussian-splats-3d";

const SplatPage = () => {
  const navigate = useNavigate();
  const containerRef = useRef(null);
  const viewerRef = useRef(null);
  const mountedRef = useRef(true);
  const [status, setStatus] = useState("loading");
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    mountedRef.current = true;
    const container = containerRef.current;
    if (!container) return;

    const viewer = new GaussianSplats3D.Viewer({
      rootElement: container,
      selfDrivenMode: true,
      sharedMemoryForWorkers: false,
      cameraUp: [0, -1, 0],
      initialCameraPosition: [0, -0.6, 3],
      initialCameraLookAt: [0, -0.6, 0],
    });

    viewerRef.current = viewer;

    const splatUrl = window.location.origin + process.env.PUBLIC_URL + "/my_table.splat";

    viewer
      .addSplatScene(splatUrl)
      .then(() => {
        if (mountedRef.current) {
          viewer.start();
          setStatus("loaded");
        }
      })
      .catch((err) => {
        if (mountedRef.current) {
          setStatus("error");
          setErrorMsg(err?.message || String(err));
        }
      });

    return () => {
      mountedRef.current = false;
      viewerRef.current = null;
      try { viewer.stop(); } catch (_) {}
    };
  }, []);

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#111", position: "relative" }}>
      <div ref={containerRef} style={{ width: "100%", height: "100%" }} />

      {status === "loading" && (
        <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)", color: "#fff", fontSize: "14px", textAlign: "center" }}>
          <div>Loading 3D scene…</div>
        </div>
      )}

      {status === "error" && (
        <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)", color: "#f66", fontSize: "14px", textAlign: "center" }}>
          <div>Failed to load scene</div>
          <div style={{ fontSize: "12px", marginTop: "8px", color: "#aaa" }}>{errorMsg}</div>
        </div>
      )}

      <div style={{ position: "absolute", top: "20px", left: "20px", zIndex: 10 }}>
        <button
          onClick={() => navigate(-1)}
          style={{
            background: "rgba(255,255,255,0.15)",
            border: "1px solid rgba(255,255,255,0.3)",
            color: "#fff",
            padding: "8px 16px",
            borderRadius: "8px",
            cursor: "pointer",
            backdropFilter: "blur(8px)",
            fontSize: "14px",
          }}
        >
          ← Back
        </button>
      </div>
      {status === "loaded" && (
        <div style={{ position: "absolute", bottom: "20px", left: "50%", transform: "translateX(-50%)", color: "rgba(255,255,255,0.4)", fontSize: "13px", zIndex: 10 }}>
          Drag to orbit · Scroll to zoom · Right-click to pan
        </div>
      )}
    </div>
  );
};

export default SplatPage;
